impl Body {
    #[effects(alloc)]
    fn quant_expr(self: &mut Body, cx: &mut FnCtx, e: &ast::Expr, q: &ast::Quant, mode: Mode, f: usize) -> ast::TypeKind
        decreases f * 3,
    {
        if f == 0 {
            return ast::TypeKind::Error;
        }
        let kw: String = quant_kw(&q.q);
        if exec_mode(mode) {
            self.c.help("E0503", e.span, types::cat3("`", kw.as_str(), "` is only allowed in specifications").as_str(), "state it in a `spec fn` used by a contract, or compute it in code with a loop");
            return ast::TypeKind::Error;
        }
        let scope: Vec<Local> = Vec::new();
        cx.scopes.push(scope);
        for i in 0..q.binders.len()
            invariant 0 <= i && i <= q.binders.len(),
        {
            if !types::is_int(&q.binders[i].ty.kind) && !types::is_error(&q.binders[i].ty.kind) {
                self.c.help("E0402", q.binders[i].ty.span, types::cat3("`", kw.as_str(), "` binders must be integers").as_str(), "bind an integer index (e.g. `i: usize`) and reach the value through it");
            }
            self.declare(cx, &q.binders[i].name, q.binders[i].ty.kind.clone(), false, false);
        }
        let mut triggers: Vec<ast::Expr> = Vec::new();
        collect_triggers(&*q.body, &mut triggers, 1000000000);
        for k in 0..triggers.len()
            invariant 0 <= k && k <= triggers.len(),
        {
            match ast::var_name(&triggers[k]) {
                None => {},
                Some(v) => { if binds(q.binders.as_slice(), v.as_str()) { let mut hint: String = types::cat5("mark a term that applies a function or an index to `", v.as_str(), "`, e.g. `#[trigger] p(", v.as_str(), ")` or `#[trigger] a["); hint.push_str(v.as_str()); hint.push_str("]`"); self.c.help("E0517", triggers[k].span, types::cat3("`#[trigger]` marks the bound variable `", v.as_str(), "` alone").as_str(), hint.as_str()); } },
            }
        }
        if triggers.len() == 0 {
            let first: Option<source::Span> = if q.binders.len() == 1 {
                first_index_on(&*q.body, q.binders[0].name.name.as_str())
            } else {
                None
            };
            let msg: String = types::cat3("`", kw.as_str(), "` has no `#[trigger]`");
            match first {
                None => self.c.help("E0511", e.span, msg.as_str(), "mark a term that mentions every bound variable, e.g. `#[trigger] a[i]`"),
                Some(at) => self.c.fixed("E0511", source::Span { file: at.file, lo: at.lo, hi: at.lo }, msg.as_str(), "mark the first term indexed by the bound variable", "#[trigger] "),
            }
        } else {
            for j in 0..q.binders.len()
                invariant 0 <= j && j <= q.binders.len(),
            {
                if !any_mentions(triggers.as_slice(), q.binders[j].name.name.as_str(), true, 1000000000) {
                    self.c.help("E0512", q.binders[j].name.span, types::cat3("no trigger mentions bound variable `", q.binders[j].name.name.as_str(), "`").as_str(), types::cat3("mark a term that mentions `", q.binders[j].name.name.as_str(), "` with `#[trigger]` as well (the triggers form one pattern)").as_str());
                }
            }
        }
        if cx.forall_depth < 4294967295 {
            cx.forall_depth = cx.forall_depth + 1;
        }
        let wb: Option<ast::TypeKind> = Some(ast::TypeKind::Bool);
        let t: ast::TypeKind = self.expr(cx, &*q.body, &wb, mode, f - 1);
        if cx.forall_depth > 0 {
            cx.forall_depth = cx.forall_depth - 1;
        }
        cx.scopes.pop();
        self.expect_ty(&t, &ast::TypeKind::Bool, q.body.span);
        ast::TypeKind::Bool
    }
}

impl Parser {
    #[effects(alloc)]
    fn attr(self: &mut Parser) -> Option<ast::Attr> {
        let lo: source::Span = self.bump();
        self.bump();
        let mut got: Option<ast::Ident> = None;
        if self.is_kw("invariant") {
            let isp: source::Span = self.bump();
            got = Some(ast::Ident { name: String::from("invariant"), span: isp });
        } else {
            got = self.ident("attribute name");
        }
        let name: ast::Ident = match got {
            None => { self.recover_attr(); return None; },
            Some(i) => i,
        };
        let mut verus_path: Option<ast::Ident> = None;
        if name.name == "verifier" && self.is_p("::") {
            match self.t.ident(1) {
                None => {},
                Some(seg) => { self.bump(); let ssp: source::Span = self.bump(); verus_path = Some(ast::Ident { name: seg, span: ssp }); },
            }
        }
        let mut args: Vec<ast::AttrArg> = Vec::new();
        if self.eat_p("(") {
            self.attr_args(&mut args);
            match self.expect_p(")") {
                None => { self.recover_attr(); return None; },
                Some(c) => {},
            }
        }
        let hi: source::Span = match self.expect_p("]") {
            None => { self.recover_attr(); return None; },
            Some(h) => h,
        };
        let span: source::Span = lo.to(hi);
        let mut verus: String = String::new();
        let mut is_verus: bool = false;
        match &verus_path {
            None => { if args.len() == 1 && name.name == "verifier" { match &args[0] { ast::AttrArg::Ident(vi) => { verus = vi.name.clone(); is_verus = true; }, ast::AttrArg::Str(s, p) => {}, ast::AttrArg::Pair(k2, v2) => {}, } } },
            Some(vp) => { if args.len() == 0 { verus = vp.name.clone(); is_verus = true; } },
        }
        if is_verus && verus == "external_body" {
            self.err_rep("E0216", span, "Verus's `verifier` attribute: BMB writes `#[external_body]`", "write `#[external_body]` (with a `#[rationale(..)]` before it)", "#[external_body]");
            return Some(ast::Attr { name: ast::Ident { name: String::from("external_body"), span: name.span }, args: Vec::new(), span: span });
        }
        match verus_path {
            None => {},
            Some(seg2) => { self.err("E0216", span, cat3("Verus's `verifier::", seg2.name.as_str(), "` attribute is not used").as_str()); return None; },
        }
        Some(ast::Attr { name: name, args: args, span: span })
    }
}

impl Body {
    #[effects(alloc)]
    fn arm_binds(self: &mut Body, mp: &str, p: &ast::Pat, tp: &str, vs: &[types::VariantSig], k: usize, by_ref: bool, by_mut: bool) -> Vec<ast::TypeKind> {
        let mut tys: Vec<ast::TypeKind> = Vec::new();
        if k >= vs.len() {
            return tys;
        }
        let n: usize = vs[k].tys.len();
        let vt: String = variant_text(tp, vs[k].name.as_str(), mp);
        if n == 0 && p.parens {
            self.c.fixed("E0427", p.span, types::cat3("`", vt.as_str(), "` has no payload").as_str(), types::cat3("write `", vt.as_str(), "`").as_str(), vt.as_str());
        } else if p.binds.len() != n {
            let msg: String = decls::counts(types::cat3("`", vt.as_str(), "` holds ").as_str(), n, " value(s), the pattern names ", p.binds.len(), "");
            self.c.fixed("E0427", p.span, msg.as_str(), "one new name or `_` per payload position", types::cat4(vt.as_str(), "(", holes(n).as_str(), ")").as_str());
        }
        for i in 0..n
            invariant 0 <= i && i <= n && n == vs[k].tys.len(),
        {
            if by_ref {
                tys.push(ast::TypeKind::Ref(by_mut, types::boxed(vs[k].tys[i].clone())));
            } else {
                tys.push(vs[k].tys[i].clone());
            }
        }
        tys
    }
}

impl Body {
    #[effects(alloc)]
    fn check_fn(self: &mut Body, d: &ast::FnDef, mp: &str, path: &str) -> () {
        let at: usize = match self.c.fns.find(path) {
            None => { return; },
            Some(i) => i,
        };
        let sig: types::FnSig = self.c.fns.items[at].clone();
        self.c.tparams = sig.generics.clone();
        let mut cx: FnCtx = new_ctx(path, mp, sig.effect, is_proof(d.kind));
        if !self.calls.has(path) {
            let none: Vec<String> = Vec::new();
            self.calls.insert(path, none);
        }
        for i in 0..d.attrs.len()
            invariant 0 <= i && i <= d.attrs.len(),
        {
            if d.attrs[i].name.name == "uses" {
                self.check_uses(&d.attrs[i], mp);
            }
        }
        for i in 0..d.params.len()
            invariant 0 <= i && i <= d.params.len(),
        {
            let ty: ast::TypeKind = self.c.canon(&d.params[i].ty, mp, true, 1000000000);
            self.check_param_type(&d.params[i].ty, d.kind, !ty_has_error(&ty, 1000000000));
            self.declare(&mut cx, &d.params[i].name, ty, false, true);
        }
        self.check_value_type(&d.ret.ty, "return type");
        if is_spec(d.kind) && named_one(&d.ret.ty.kind, "Vec") {
            self.spec_vec(d.ret.ty.span);
        }
        if is_spec(d.kind) && named_one(&d.ret.ty.kind, "String") {
            self.spec_string(d.ret.ty.span);
        }
        let ret_ty: ast::TypeKind = self.c.canon(&d.ret.ty, mp, true, 1000000000);
        cx.ret = ret_ty.clone();
        if is_spec(d.kind) {
            if d.pre.len() > 0 {
                self.c.err("E0207", d.pre[0].span, "spec functions take no `requires` / `ensures` in milestone 1");
            } else if d.post.len() > 0 {
                self.c.err("E0207", d.post[0].span, "spec functions take no `requires` / `ensures` in milestone 1");
            }
        }
        for i in 0..d.pre.len()
            invariant 0 <= i && i <= d.pre.len(),
        {
            self.check_contract(&mut cx, &d.pre[i], false);
        }
        if d.post.len() > 0 {
            let scope: Vec<Local> = Vec::new();
            cx.scopes.push(scope);
            match &d.ret.name {
                None => {},
                Some(n) => self.declare(&mut cx, n, ret_ty.clone(), false, false),
            }
            for i in 0..d.post.len()
                invariant 0 <= i && i <= d.post.len(),
            {
                self.check_contract(&mut cx, &d.post[i], true);
            }
            cx.scopes.pop();
        }
        match &d.ret.name {
            None => {},
            Some(n) => { types::add(&mut cx.reserved, n.name.as_str()); },
        }
        match &d.measure {
            None => {},
            Some(m) => { let no: Option<ast::TypeKind> = None; let t: ast::TypeKind = self.expr(&mut cx, m, &no, Mode::Spec(false), 1000000000); self.measure_type(&t, m.span); },
        }
        if is_some(&sig.trait_of) && !sig.default {
            self.c.tparams = Vec::new();
            return;
        }
        let mode: Mode = match d.kind {
            ast::FnKind::Exec => Mode::Exec,
            ast::FnKind::Spec => Mode::Spec(false),
            ast::FnKind::Proof => Mode::Ghost,
        };
        let want: Option<ast::TypeKind> = Some(ret_ty.clone());
        self.open_lets = Vec::new();
        self.typed_uses = Vec::new();
        self.spec_at = Vec::new();
        let t: ast::TypeKind = self.block(&mut cx, &d.body, &want, mode, 1000000000);
        self.spec_widen = !is_exec(d.kind);
        let end: source::Span = match &d.body.tail {
            None => d.body.span,
            Some(e) => e.span,
        };
        self.expect_ty(&t, &ret_ty, end);
        self.spec_widen = false;
        self.settle_lets(d, mp);
        if is_exec(d.kind) {
            if has_attr(d.attrs.as_slice(), "external_body") {
                need_own(&mut cx, panic_effect(), "`#[external_body]`");
                types::add(&mut self.external, path);
            }
            self.check_effects(d, &cx);
            let info: moves::MoveInfo = self.check_moves(d, path);
            self.needs.insert(path, Needs { own: cx.own, body: needed(&cx), moves: info });
        }
        self.c.tparams = Vec::new();
    }

    #[effects(alloc)]
    fn trait_cycles(self: &mut Body, defs: &table::Table<DefRow>) -> Vec<String> {
        let mut edges: table::Table<Vec<Edge>> = table::new::<Vec<Edge>>();
        for i in 0..self.gcalls.len()
            invariant 0 <= i && i <= self.gcalls.len(),
        {
            add_edge(&mut edges, self.gcalls[i].caller.as_str(), Edge { callee: self.gcalls[i].callee.clone(), args: self.gcalls[i].args.clone() });
        }
        let callers: usize = self.calls.len();
        for n in 0..callers
            invariant 0 <= n && n <= callers,
        {
            match self.calls.nth(n) {
                None => {},
                Some(at) => { let caller: String = self.calls.key(n); let cs: Vec<String> = decls::sorted(self.calls.items[at].as_slice()); for j in 0..cs.len() invariant 0 <= j && j <= cs.len(), { if self.plain_fn(cs[j].as_str()) { let none: Vec<ast::TypeKind> = Vec::new(); add_edge(&mut edges, caller.as_str(), Edge { callee: cs[j].clone(), args: none }); } } },
            }
        }
        let mut graph: table::Table<Vec<String>> = table::new::<Vec<String>>();
        let mut bound_edges: Vec<Pair> = Vec::new();
        let mut base_of: table::Table<String> = table::new::<String>();
        let mut work: Vec<Edge> = Vec::new();
        let total: usize = defs.len();
        for n in 0..total
            invariant 0 <= n && n <= total,
        {
            let path: String = defs.key(n);
            if self.plain_fn(path.as_str()) {
                let none: Vec<ast::TypeKind> = Vec::new();
                work.push(Edge { callee: path.clone(), args: none });
            }
        }
        let mut fuel: usize = 1000000000;
        while work.len() > 0 && fuel > 0
            invariant 0 <= fuel,
            decreases fuel,
        {
            fuel = fuel - 1;
            match work.pop() {
                None => {},
                Some(w) => { self.instance_edges(&w, &edges, &mut graph, &mut bound_edges, &mut base_of, &mut work); },
            }
        }
        let mut out: Vec<String> = Vec::new();
        let comps: Vec<Vec<String>> = sccs_with_cycles(&graph);
        for i in 0..comps.len()
            invariant 0 <= i && i <= comps.len(),
        {
            match first_bound(bound_edges.as_slice(), comps[i].as_slice()) {
                None => {},
                Some(to) => { for j in 0..comps[i].len() invariant 0 <= j && j <= comps[i].len(), { match base_of.find(comps[i][j].as_str()) { None => {}, Some(at) => { let b: String = base_of.items[at].clone(); if types::add(&mut out, b.as_str()) { match defs.find(b.as_str()) { None => {}, Some(d) => { self.c.help("E0207", defs.items[d].span, types::cat5("`", b.as_str(), "` is recursive through a call on a bounded `Self` (reaching `", to.as_str(), "`), which carries no measure (ADR-0046 §4)").as_str(), "call with a known `Self` type, or break the cycle"); }, } } }, } } },
            }
        }
        out
    }
}

impl Checker {
    #[effects(alloc)]
    fn trait_sigs(self: &mut Checker, m: &ast::Mod, prefix: &str, f: usize) -> ()
        decreases f,
    {
        if f == 0 {
            return;
        }
        let mp: String = unit_path(prefix, m);
        let sub: String = types::cat2(mp.as_str(), "::");
        for s in 0..m.mods.len()
            invariant 0 <= s && s <= m.mods.len(),
        {
            self.trait_sigs(&m.mods[s], sub.as_str(), f - 1);
        }
        for i in 0..m.traits.len()
            invariant 0 <= i && i <= m.traits.len(),
        {
            let path: String = types::cat3(mp.as_str(), "::", m.traits[i].name.name.as_str());
            let mine: bool = match self.traits.find(path.as_str()) {
                None => false,
                Some(at) => span_eq(self.traits.items[at].span, m.traits[i].name.span),
            };
            if mine {
                let mut sb: Vec<String> = Vec::new();
                sb.push(path.clone());
                let selfp: types::TParam = types::TParam { name: String::from("Self"), bounds: sb };
                let mut ig: Vec<types::TParam> = Vec::new();
                ig.push(selfp.clone());
                let mut names: Vec<String> = Vec::new();
                for k in 0..m.traits[i].fns.len()
                    invariant 0 <= k && k <= m.traits[i].fns.len() && i < m.traits.len(),
                {
                    let fname: String = m.traits[i].fns[k].f.name.name.clone();
                    if types::has(names.as_slice(), fname.as_str()) {
                        self.err("E0302", m.traits[i].fns[k].f.name.span, types::cat5("`", fname.as_str(), "` is defined more than once in trait `", m.traits[i].name.name.as_str(), "`").as_str());
                    } else {
                        names.push(fname.clone());
                        match &m.traits[i].fns[k].f.measure {
                            None => {},
                            Some(d) => { self.help("E0207", d.span, "a trait method takes no `decreases`: recursion through a bound is not supported", "remove it; an impl's function may recurse on its own type with its own `decreases`"); },
                        }
                        let own: Vec<types::TParam> = self.tparams_of(m.traits[i].fns[k].f.generics.as_slice(), false, mp.as_str());
                        let mut tps: Vec<types::TParam> = Vec::new();
                        tps.push(selfp.clone());
                        ast::append::<types::TParam>(&mut tps, own);
                        self.tparams = tps;
                        self.receiver_rule(&m.traits[i].fns[k].f, "Self", true, mp.as_str());
                        self.tparams = Vec::new();
                        let fp: String = types::cat3(path.as_str(), "::", fname.as_str());
                        self.collect_fn(&m.traits[i].fns[k].f, fp.as_str(), mp.as_str(), false, ig.as_slice());
                        match self.fns.find(fp.as_str()) {
                            None => {},
                            Some(at) => { self.fns.items[at].trait_of = Some(path.clone()); self.fns.items[at].default = m.traits[i].fns[k].has_body; },
                        }
                    }
                }
                match self.traits.find(path.as_str()) {
                    None => { let dropped: Vec<String> = names; },
                    Some(at) => { self.traits.items[at].methods = names; },
                }
            }
        }
    }
}

impl Parser {
    #[effects(alloc)]
    fn no_pub(self: &mut Parser) -> () {
        if self.is_kw("pub") {
            let sp: source::Span = self.bump();
            self.err_rep("E0207", sp, "`pub` is not used; every definition of a unit is part of its surface", "remove `pub`", "");
        }
    }

    #[effects(alloc)]
    fn parse_generics(self: &mut Parser, d: usize) -> Vec<ast::TypeParam>
        requires d <= 256,
    {
        let mut out: Vec<ast::TypeParam> = Vec::new();
        self.generics_span = None;
        if !self.is_p("<") {
            return out;
        }
        let lo: source::Span = self.bump();
        let mut n: usize = self.left();
        while n > 0 && !self.is_p(">") && !self.eof()
            decreases n,
        {
            n = n - 1;
            if !self.eat_p(",") {
                if self.is_kw("const") {
                    self.err_fix_here("E0207", "const generic parameters are not supported (ADR-0046 open question 1)", "take the length as a value: a slice `&[T]` and its `len()`");
                    self.skip_angle_from();
                    return out;
                }
                let name: ast::Ident = match self.ident("type parameter") {
                    None => { self.skip_angle_from(); return out; },
                    Some(i) => i,
                };
                let mut bounds: Vec<Vec<ast::Ident>> = Vec::new();
                let mut fn_bound: Option<ast::FnBound> = None;
                if self.eat_p(":") {
                    let mut m: usize = self.left();
                    while m > 0
                        decreases m,
                    {
                        m = m - 1;
                        if (self.is_kw("Fn") || self.is_kw("FnMut") || self.is_kw("FnOnce")) && self.t.is_p(1, "(") {
                            let kind: ast::FnTrait = if self.is_kw("Fn") {
                                ast::FnTrait::Fn
                            } else if self.is_kw("FnMut") {
                                ast::FnTrait::FnMut
                            } else {
                                ast::FnTrait::FnOnce
                            };
                            let at: source::Span = self.bump();
                            self.bump();
                            let mut params: Vec<ast::Type> = Vec::new();
                            let mut q: usize = self.left();
                            while q > 0 && !self.is_p(")") && !self.eof()
                                decreases q,
                            {
                                q = q - 1;
                                params.push(self.parse_type(d));
                                if !self.eat_p(",") {
                                    q = 0;
                                }
                            }
                            self.expect_p(")");
                            let ret: ast::Type = if self.eat_p("->") {
                                self.parse_type(d)
                            } else {
                                ast::Type { kind: ast::TypeKind::Unit, span: self.prev_span() }
                            };
                            fn_bound = Some(ast::FnBound { kind: kind, params: params, ret: ret, span: at.to(self.prev_span()) });
                            if !self.eat_p("+") {
                                m = 0;
                            }
                        } else {
                            let path: Vec<ast::Ident> = self.bound_path();
                            if path.len() == 0 {
                                self.err_expected("trait bound");
                                self.skip_angle_from();
                                return out;
                            }
                            bounds.push(path);
                            if !self.eat_p("+") {
                                m = 0;
                            }
                        }
                    }
                }
                let span: source::Span = name.span.to(self.prev_span());
                out.push(ast::TypeParam { name: name, bounds: bounds, fn_bound: fn_bound, span: span });
                if !self.eat_p(",") {
                    n = 0;
                }
            }
        }
        match self.expect_p(">") {
            None => {},
            Some(hi) => { self.generics_span = Some(lo.to(hi)); },
        }
        out
    }

    #[effects(alloc)]
    fn parse_mod_inner(self: &mut Parser, attrs: Vec<ast::Attr>, d: usize) -> Option<ast::Mod>
        requires d <= 256,
        decreases (256 - d) * 64 + 60,
    {
        let lo: source::Span = self.bump();
        let name: ast::Ident = self.ident("module name")?;
        self.units.push(name.name.clone());
        self.expect_p("{")?;
        let mut fns: Vec<ast::FnDef> = Vec::new();
        let mut mods: Vec<ast::Mod> = Vec::new();
        let mut types: Vec<ast::TypeDef> = Vec::new();
        let mut impls: Vec<ast::Impl> = Vec::new();
        let mut traits: Vec<ast::TraitDef> = Vec::new();
        let mut trait_impls: Vec<ast::TraitImpl> = Vec::new();
        let mut uses: Vec<ast::UseItem> = Vec::new();
        let mut consts: Vec<ast::ConstDef> = Vec::new();
        let mut n: usize = self.left();
        while n > 0 && !self.is_p("}") && !self.eof()
            decreases n,
        {
            n = n - 1;
            let start: usize = self.t.pos;
            let item_attrs: Vec<ast::Attr> = self.attrs();
            self.no_pub();
            if self.is_kw("const") {
                match self.parse_const(item_attrs, d) {
                    None => self.recover_item(),
                    Some(c) => consts.push(c),
                }
            } else if self.is_kw("mod") {
                match self.parse_mod(item_attrs, d) {
                    None => self.recover_item(),
                    Some(m) => mods.push(m),
                }
            } else if self.is_kw("fn") || (self.is_kw("spec") || self.is_kw("proof")) && self.t.is_kw(1, "fn") {
                match self.parse_fn(item_attrs, d) {
                    None => self.recover_item(),
                    Some(f) => fns.push(f),
                }
            } else if self.is_kw("struct") || self.is_kw("enum") {
                match self.parse_type_def(item_attrs, d) {
                    None => self.recover_item(),
                    Some(t) => types.push(t),
                }
            } else if self.is_kw("impl") {
                let mut k: usize = 0;
                while k < item_attrs.len()
                    decreases item_attrs.len() - k,
                {
                    self.err_rep("E0605", item_attrs[k].span, cat3("unknown attribute `", item_attrs[k].name.name.as_str(), "` on an `impl` block").as_str(), "an `impl` block takes no attributes: write it on the functions inside", "");
                    k = k + 1;
                }
                match self.parse_impl(d) {
                    None => self.recover_item(),
                    Some(it) => { match it { ImplItem::Inherent(i) => impls.push(i), ImplItem::Trait(ti) => trait_impls.push(ti), } },
                }
            } else if self.is_kw("trait") {
                match self.parse_trait(item_attrs, d) {
                    None => self.recover_item(),
                    Some(tr) => traits.push(tr),
                }
            } else if self.is_kw("use") {
                match self.parse_use() {
                    None => {},
                    Some(u) => uses.push(u),
                }
            } else if unsupported_item(text_of(self.t.ident(0)).as_str()) {
                let s: String = text_of(self.t.ident(0));
                let sp: source::Span = self.span();
                if s == "unsafe" {
                    self.unsafe_habit(sp);
                } else if s == "static" {
                    if self.t.is_kw(1, "mut") {
                        self.err_fix("E0261", sp, "`static` items are not used", "global mutable state is passed as an argument (DESIGN §4.1 \"Effects\")");
                    } else {
                        self.err_rep("E0261", sp, "`static` items are not used", "write `const`", "const");
                    }
                } else {
                    self.err_fix("E0207", sp, cat3("`", s.as_str(), "` items are not supported in milestone 1").as_str(), "units hold `fn`, `spec fn`, `const`, `struct`, `enum`, `trait` and `impl`");
                }
                self.bump();
                self.recover_item();
            } else {
                self.err_expected("`fn`, `spec fn` or `mod`");
                if !self.is_p("}") {
                    self.bump();
                    self.recover_item();
                }
            }
            if self.t.pos == start {
                self.bump();
            }
        }
        let hi: source::Span = self.expect_p("}")?;
        let lens: Vec<ast::Len> = std::mem::replace(&mut self.lens, Vec::new());
        Some(ast::Mod { name: name, attrs: attrs, fns: fns, mods: mods, types: types, impls: impls, traits: traits, trait_impls: trait_impls, uses: uses, consts: consts, lens: lens, span: lo.to(hi) })
    }

    #[effects(alloc)]
    fn parse_trait(self: &mut Parser, attrs: Vec<ast::Attr>, d: usize) -> Option<ast::TraitDef>
        requires d <= 256,
    {
        let lo: source::Span = self.bump();
        let name: ast::Ident = self.ident("trait name")?;
        if self.is_p("<") {
            self.err_fix_here("E0207", "generic traits are not supported (ADR-0046 §1)", "put the type parameters on the methods");
            self.skip_angle();
        }
        if self.is_p(":") {
            self.err_fix_here("E0207", "supertraits are not supported (ADR-0046 §1)", "bound the type parameters by each trait: `T: A + B`");
            let mut k: usize = self.left();
            while k > 0 && !self.is_p("{") && !self.eof()
                decreases k,
            {
                k = k - 1;
                self.bump();
            }
        }
        self.expect_p("{")?;
        let mut fns: Vec<ast::TraitFn> = Vec::new();
        let outer: Option<String> = std::mem::replace(&mut self.impl_ty, Some(String::from("Self")));
        let mut n: usize = self.left();
        while n > 0 && !self.is_p("}") && !self.eof()
            decreases n,
        {
            n = n - 1;
            let start: usize = self.t.pos;
            let fattrs: Vec<ast::Attr> = self.attrs();
            self.no_pub();
            if self.is_kw("fn") || self.is_kw("spec") && self.t.is_kw(1, "fn") {
                self.decl_ok = true;
                let r: Option<ast::FnDef> = self.parse_fn(fattrs, d);
                let has_body: bool = !self.decl_ok;
                self.decl_ok = false;
                match r {
                    None => self.recover_item(),
                    Some(f) => fns.push(ast::TraitFn { f: f, has_body: has_body }),
                }
            } else {
                self.err_expected("`fn` or `spec fn`");
                self.bump();
                self.recover_item();
            }
            if self.t.pos == start {
                self.bump();
            }
        }
        self.impl_ty = outer;
        let hi: source::Span = self.expect_p("}")?;
        Some(ast::TraitDef { name: name, attrs: attrs, fns: fns, span: lo.to(hi) })
    }
}

impl Checker {
    #[effects(alloc)]
    fn receiver_rule(self: &mut Checker, f: &ast::FnDef, impl_ty: &str, has: bool, mp: &str) -> () {
        for k in 0..f.params.len()
            invariant 0 <= k && k <= f.params.len(),
        {
            let ty: ast::TypeKind = self.canon(&f.params[k].ty, mp, false, 100000);
            let v: ast::TypeKind = types::value(&ty);
            let receiver_type: bool = has && !types::is_error(&v) && (match types::named_path(&v) { None => types::text(&v).as_str() == impl_ty, Some(np) => np.as_str() == impl_ty, });
            let is_self: bool = f.params[k].name.name.as_str() == "self";
            if k == 0 && receiver_type && !is_self {
                self.help("E0310", f.params[k].name.span, types::cat3("the receiver of `", f.name.name.as_str(), "` is named `self`").as_str(), types::cat3("rename `", f.params[k].name.name.as_str(), "` to `self` in the signature and the body").as_str());
            } else if is_self && (k != 0 || !receiver_type) && !types::is_error(&ty) {
                self.help("E0310", f.params[k].name.span, "`self` names only the receiver: the first parameter of an `impl T` function, typed `T`, `&T` or `&mut T`", "choose another name");
            }
        }
    }
}

impl Body {
    #[effects(alloc)]
    fn quant_expr(self: &mut Body, cx: &mut FnCtx, e: &ast::Expr, q: &ast::Quant, mode: Mode, f: usize) -> ast::TypeKind
        decreases f * 3,
    {
        if f == 0 {
            return ast::TypeKind::Error;
        }
        let kw: String = quant_kw(&q.q);
        if exec_mode(mode) {
            self.c.help("E0503", e.span, types::cat3("`", kw.as_str(), "` is only allowed in specifications").as_str(), "state it in a `spec fn` used by a contract, or compute it in code with a loop");
            return ast::TypeKind::Error;
        }
        let scope: Vec<Local> = Vec::new();
        cx.scopes.push(scope);
        for i in 0..q.binders.len()
            invariant 0 <= i && i <= q.binders.len(),
        {
            if !types::is_int(&q.binders[i].ty.kind) && !types::is_error(&q.binders[i].ty.kind) {
                self.c.help("E0402", q.binders[i].ty.span, types::cat3("`", kw.as_str(), "` binders must be integers").as_str(), "bind an integer index (e.g. `i: usize`) and reach the value through it");
            }
            self.declare(cx, &q.binders[i].name, q.binders[i].ty.kind.clone(), false, false);
        }
        let mut triggers: Vec<ast::Expr> = Vec::new();
        collect_triggers(&*q.body, &mut triggers, 1000000000);
        for k in 0..triggers.len()
            invariant 0 <= k && k <= triggers.len(),
        {
            match ast::var_name(&triggers[k]) {
                None => {},
                Some(v) => { if binds(q.binders.as_slice(), v.as_str()) { let mut hint: String = types::cat5("mark a term that applies a function or an index to `", v.as_str(), "`, e.g. `#[trigger] p(", v.as_str(), ")` or `#[trigger] a["); hint.push_str(v.as_str()); hint.push_str("]`"); self.c.help("E0517", triggers[k].span, types::cat3("`#[trigger]` marks the bound variable `", v.as_str(), "` alone").as_str(), hint.as_str()); } },
            }
        }
        if triggers.len() == 0 {
            let first: Option<source::Span> = if q.binders.len() == 1 {
                first_index_on(&*q.body, q.binders[0].name.name.as_str())
            } else {
                None
            };
            let msg: String = types::cat3("`", kw.as_str(), "` has no `#[trigger]`");
            match first {
                None => self.c.help("E0511", e.span, msg.as_str(), "mark a term that mentions every bound variable, e.g. `#[trigger] a[i]`"),
                Some(at) => self.c.fixed("E0511", source::Span { file: at.file, lo: at.lo, hi: at.lo }, msg.as_str(), "mark the first term indexed by the bound variable", "#[trigger] "),
            }
        } else {
            for j in 0..q.binders.len()
                invariant 0 <= j && j <= q.binders.len(),
            {
                if !any_mentions(triggers.as_slice(), q.binders[j].name.name.as_str(), true, 1000000000) {
                    self.c.help("E0512", q.binders[j].name.span, types::cat3("no trigger mentions bound variable `", q.binders[j].name.name.as_str(), "`").as_str(), types::cat3("mark a term that mentions `", q.binders[j].name.name.as_str(), "` with `#[trigger]` as well (the triggers form one pattern)").as_str());
                }
            }
        }
        if cx.forall_depth < 4294967295 {
            cx.forall_depth = cx.forall_depth + 1;
        }
        let wb: Option<ast::TypeKind> = Some(ast::TypeKind::Bool);
        let t: ast::TypeKind = self.expr(cx, &*q.body, &wb, mode, f - 1);
        if cx.forall_depth > 0 {
            cx.forall_depth = cx.forall_depth - 1;
        }
        cx.scopes.pop();
        self.expect_ty(&t, &ast::TypeKind::Bool, q.body.span);
        ast::TypeKind::Bool
    }
}

#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}

